/* thr_rot_816_64x27 : registre de seuils tournant du bloc 8 (cache + banque en anneau), IP de pile_8mux.py : 64 voies x 27
 * positions, K 1 G 6, blocs de 285 bits. Modele en phases : cache maitre (lm) / esclave (ls) ; banque LSS
 * (lss) derriere le mux (s = 1 : la latch du tri, s = 0 : l'esclave) ; latch du tri (ll, phase opposee) entre l'o de la
 * case suivante et a. Contrat : i_thr_we & ~i_thr_rot (chargement) jamais au cycle d'une avance. */
(* blackbox *)
module thr_rot_816_64x27 (input i_phi1, input i_phi2, input i_thr_cache_valid, input i_thr_we, input i_thr_rot, input [63:0] i_thr_cache_data, output [284:0] o_theta);
`ifndef SYNTHESIS
    reg r_valid_c, r_we_c, r_rot_c;
    always_latch if (i_phi1) begin r_valid_c = i_thr_cache_valid; r_we_c = i_thr_we; r_rot_c = i_thr_rot; end
    wire lm = i_phi1 & i_thr_cache_valid, ls = i_phi2 & r_valid_c, lss = i_phi2 & r_we_c, s = r_rot_c,
         ll = i_phi1 & i_thr_rot;
    always @(posedge i_phi2) if (r_valid_c && r_we_c && !r_rot_c)
        $error("thr_rot_816_64x27 : chargement au cycle d'une avance : hors contrat");
    reg [1727:0] m, sl, bank, r_tri;   // bit i = W n + w
    wire [1727:0] nxt = {i_thr_cache_data, sl[1727:64]};   // le maitre de n prend l'esclave de n + 1
    wire [1727:0] boucle;   // boucle[i] = bank[src(i)] : l'o de la case suivante
